import sys,random,time,networkx as nx
sys.path.insert(0,'/workspace/submission')
from fastgen import fast_generate
for nt in [300,1000,3000]:
 random.seed(9000+nt);n=32
 H=nx.DiGraph();H.add_nodes_from(range(n));loads={};roots={i:0 for i in range(n)}
 for k in range(nt):
  T=[]
  for v in range(1,n):T.append((random.randrange(v),v))
  root=random.randrange(n);w=random.randint(1,10)
  adj={i:[] for i in range(n)}
  for a,b in T:adj[a].append(b);adj[b].append(a)
  st=[root];seen={root}
  while st:
   x=st.pop()
   for y in adj[x]:
    if y not in seen:seen.add(y);loads[(x,y)]=loads.get((x,y),0)+w;st.append(y)
  roots[root]+=w
 for (a,b),c in loads.items():H.add_edge(a,b,capacity=c)
 t=time.time()
 try:Ts,Cs=fast_generate(H,list(range(n)),roots)
 except Exception as e:print('nt',nt,'FAIL',repr(e));continue
 print('nt',nt,'D',sum(roots.values()),'arcs',H.number_of_edges(),'records',len(Ts),'time',round(time.time()-t,2),flush=True)
PY
